import { expect, test } from 'vitest';
import { readFileSync } from 'fs';
import { createHash } from 'crypto';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import parser from '../dist/autoit3';
import { isPeggySyntaxError } from './helpers';

const HERE = dirname(fileURLToPath(import.meta.url));

// `LineContinuationCases.au3` is generated by generateLineContinuationCases.mjs
// and enumerates every position where a line continuation may legally appear,
// paired with the whitespace variants that must all parse the same way.
//
// The `__` rule sits between almost every pair of tokens, so a change to how it
// consumes whitespace is easy to get subtly wrong. These tests are the guard for
// that. Regenerate the fixture with:
//   node tests/generateLineContinuationCases.mjs
const cases = readFileSync(join(HERE, 'LineContinuationCases.au3'), 'utf8');
const negatives = JSON.parse(
    readFileSync(join(HERE, 'LineContinuationNegativeCases.json'), 'utf8')
) as Record<string, string>;

// A hash of the whole AST rather than a vitest snapshot: the AST for 497 cases is
// around 3 MiB of JSON, which is far too large to keep as a readable snapshot.
// If this hash changes, the whitespace handling changed, which is exactly the
// regression this fixture exists to catch. Regenerate with:
//   node -e 'console.log(require("crypto").createHash("sha256").update(JSON.stringify(require("./dist/autoit3").default.parse(require("fs").readFileSync("tests/LineContinuationCases.au3","utf8"),{grammarSource:""}))).digest("hex"))'
test('LineContinuationCasesTest', () => {
    const ast = parser.parse(cases, { grammarSource: '' });
    const hash = createHash('sha256').update(JSON.stringify(ast)).digest('hex');

    expect(hash).toStrictEqual('3d1e67ca4953ed1b291d3b06f2e2c6a9524cce1323720c93bd3c0a39a362b74a');
});

test('every construct in the fixture parsed', () => {
    const ast = parser.parse(cases, { grammarSource: '' });

    // Top level counts only. WithStatement and most other constructs live inside
    // the generated functions, so they are counted by walking the whole tree.
    const countTop = (type: string) => ast.body.filter((n) => n.type === type).length;
    const countAll = (type: string) => {
        let n = 0;
        const walk = (node: unknown): void => {
            if (Array.isArray(node)) {
                node.forEach(walk);
            } else if (node && typeof node === 'object') {
                const o = node as Record<string, unknown>;
                if (o.type === type) n++;
                Object.values(o).forEach(walk);
            }
        };
        walk(ast);
        return n;
    };

    expect(ast.type).toBe('Program');
    expect(ast.body.length).toBe(1860);
    // Sanity check that each generated group really made it into the AST.
    expect(countTop('FunctionDeclaration')).toBe(407);
    expect(countTop('EnumDeclaration')).toBe(90);
    // One per whitespace variant.
    expect(countAll('WithStatement')).toBe(9);
    // One per whitespace variant.
    expect(countAll('SwitchStatement')).toBe(18);
    // The old `__` rule emitted a spurious `ExpressionStatement` referencing an
    // identifier `_` for the second of two consecutive continuations. It must
    // not come back.
    expect(countTop('ExpressionStatement')).toBe(10);
});

test('consecutive line continuations join into one statement', () => {
    // Two continuations in a row, each with its own leading whitespace. The old
    // `__` rule consumed the second continuation's leading whitespace as the
    // trailing whitespace of the first, so the second `_` fell out of the
    // continuation and was parsed as an identifier, splitting the statement.
    const src = [
        'Func f()',
        '\tLocal $a = 1 + _',
        '\t _',
        '\t 2',
        '\tReturn $a',
        'EndFunc',
        '',
    ].join('\n');
    const ast = parser.parse(src, { grammarSource: '' }) as { body: Array<{ type: string; body: unknown[] }> };

    expect(ast.body).toHaveLength(1);
    const fn = ast.body[0] as unknown as { body: unknown[] };
    expect(fn.body).toHaveLength(2);
});

test.each(Object.keys(negatives))('rejects invalid continuation: %s', (name) => {
    let thrown: unknown = null;
    try {
        parser.parse(negatives[name], { grammarSource: '' });
    } catch (error) {
        expect(isPeggySyntaxError(error)).toBe(true);
        thrown = error;
    }

    expect(thrown).not.toBe(null);
});